CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_payment_health_mv TO {{DB}}.gold_payment_health (`dt` Date, `payment_method` String, `provider` String, `status` String, `cnt` UInt64, `total_amount` Decimal(38, 2)) AS SELECT toDate(event_time) AS dt, payment_method, provider, toString(status) AS status, count() AS cnt, sum(amount) AS total_amount FROM {{DB}}.payment_events GROUP BY dt, payment_method, provider, status;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_product_performance_mv TO {{DB}}.gold_product_performance (`dt` Date, `product_sku` String, `product_name` String, `category` String, `orders` UInt64, `units_sold` UInt64, `revenue` Decimal(38, 2)) AS SELECT toDate(event_time) AS dt, product_sku, product_name, category, count() AS orders, sum(quantity) AS units_sold, sum(total_amount) AS revenue FROM {{DB}}.order_events GROUP BY dt, product_sku, product_name, category;

CREATE MATERIALIZED VIEW IF NOT EXISTS {{DB}}.gold_revenue_daily_mv TO {{DB}}.gold_revenue_daily (`dt` Date, `country` String, `channel` String, `category` String, `orders` UInt64, `revenue` Decimal(38, 2), `units_sold` UInt64, `unique_customers` AggregateFunction(uniq, UInt32)) AS SELECT toDate(event_time) AS dt, country, channel, category, count() AS orders, sum(total_amount) AS revenue, sum(quantity) AS units_sold, uniqState(customer_id) AS unique_customers FROM {{DB}}.order_events GROUP BY dt, country, channel, category;
